use glam::DVec3;use ingetrazo_gui::IngeTrazoApp;use ingetrazo_core::{groups::Group,section::SectionPlane};use ingetrazo_render::style::VisualStyle;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let mut app=IngeTrazoApp::new();let mut parent=Group::new("parent");let mut child=Group::new("child");child.hidden=true;parent.children.push(child);app.scene.groups.push(parent);app.scene.section_planes.push(SectionPlane::new(DVec3::ZERO,DVec3::Z,"cut","A"));app.style.visual_style=VisualStyle::XRay;app.shadows_enabled=true;app.camera.two_point=true;app.camera.target=DVec3::new(2.,3.,4.);app.add_saved_view("first".into());app.add_saved_view("second".into());
 app.scene.saved_views[1].native_document=serde_json::json!({"vendor_view":{"retain":17}});app.scene.saved_views[1].style.as_mut().unwrap()["vendor_style"]=serde_json::json!(19);let first=app.scene.saved_views[0].clone();app.camera.distance=33.;app.update_selected_saved_view();assert_eq!(app.scene.saved_views[0],first);app.rename_selected_saved_view("updated second".into());app.scene.groups[0].children[0].hidden=false;app.scene.section_planes[0].active=false;app.style.visual_style=VisualStyle::Wireframe;app.shadows_enabled=false;app.camera.two_point=false;app.apply_saved_view(1);assert!(app.scene.groups[0].children[0].hidden&&app.scene.section_planes[0].active&&app.shadows_enabled&&app.camera.two_point);assert_eq!(app.camera.distance,33.);assert_eq!(app.style.visual_style,VisualStyle::XRay);ingetrazo_formats::igz::save_igz(&app.scene,&dir.join("views.igz")).unwrap();let version=app.scene.version;assert!(app.undo_stack.is_empty()&&app.redo_stack.is_empty());app.remove_selected_saved_view();assert_eq!(app.scene.version,version+1);assert_eq!(app.scene.saved_views,vec![first]);let after_delete=app.scene.clone();app.undo();assert_eq!(app.scene,after_delete);app.redo();assert_eq!(app.scene,after_delete);assert!(app.undo_stack.is_empty()&&app.redo_stack.is_empty());}
